LAYER
  NAME "gebco_latest_shaded_relief"
  TYPE RASTER
  STATUS ON
  CONNECTIONTYPE WMS
  CONNECTION "https://wms.gebco.net/2026/mapserv?"

  PROJECTION
    "init=epsg:4326"
  END

  METADATA
    "wms_title" "GEBCO 2026 Global Bathymetry and Topography"
    "wms_abstract" "This map displays a shaded-relief visualisation of global bathymetry and topography derived from the GEBCO 2026 Grid, produced by the General Bathymetric Chart of the Oceans (GEBCO). Variations in colour, light and shadow illustrate the shape of the ocean floor and land surface, highlighting underwater features such as mid-ocean ridges, seamounts, deep-sea trenches and continental slopes. It helps users explore the physical structure of the ocean, understand the diversity of seafloor landscapes and identify features that influence marine environments."
    "wms_name" "gebco_2026"
    "wms_server_version" "1.3.0"
    "wms_format" "image/png"
    "wms_srs" "EPSG:4326"
    "wms_extent" "-180 -90 180 90"
    "wms_connectiontimeout" "60"
    "wms_attribution_text" "General Bathymetric Chart of the Oceans (GEBCO)"
    "wms_attribution_onlineresource" "https://www.gebco.net/"
    "wms_metadataurl_href" "https://www.gebco.net/data-products/gebco-web-services/web-map-service"
    "wms_metadataurl_format" "text/html"
    "wms_metadataurl_type" "TC211"
  END
END
